RAILS_ENV=test bin/rails runner '
require "socket"
require "net/http"
require "json"
require "websocket/driver"

class CdpClient
  class DriverEnv
    attr_reader :url
    def initialize(socket, url)
      @socket = socket
      @url = url
    end
    def write(data)
      @socket.write(data)
    end
  end

  def initialize(ws_url)
    uri = URI(ws_url)
    @socket = TCPSocket.new(uri.host, uri.port)
    @env = DriverEnv.new(@socket, ws_url)
    @driver = WebSocket::Driver.client(@env)
    @messages = []
    @events = []
    @open = false
    @id = 0

    @driver.on(:open) { @open = true }
    @driver.on(:message) do |event|
      msg = JSON.parse(event.data)
      if msg["id"]
        @messages << msg
      else
        @events << msg
      end
    end

    @driver.start
    pump until @open
  end

  def pump
    data = @socket.readpartial(65536)
    @driver.parse(data)
  end

  def call(method, params = {})
    @id += 1
    req_id = @id
    @driver.text(JSON.generate({ id: req_id, method: method, params: params }))
    loop do
      found = @messages.find { |m| m["id"] == req_id }
      if found
        @messages.delete(found)
        raise "CDP error: #{found["error"]}" if found["error"]
        return found["result"]
      end
      pump
    end
  end

  def eval_js(expr)
    res = call("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })
    raise "JS exception: #{res["exceptionDetails"]}" if res["exceptionDetails"]
    res.dig("result", "value")
  end

  def close
    @socket.close rescue nil
  end
end

# Load fixtures into test DB for the server
system("RAILS_ENV=test bin/rails db:fixtures:load", exception: true)

server_port = TCPServer.open("127.0.0.1", 0) { |s| s.addr[1] }
debug_port  = TCPServer.open("127.0.0.1", 0) { |s| s.addr[1] }

puma_pid = spawn({ "RAILS_ENV" => "test" }, "bin/rails", "server", "-p", server_port.to_s, "-b", "127.0.0.1", out: "/tmp/puma_qa.log", err: "/tmp/puma_qa.log")
chrome_pid = spawn("chromium", "--headless", "--no-sandbox", "--disable-gpu", "--remote-debugging-port=#{debug_port}", "about:blank", out: "/tmp/chrome_qa.log", err: "/tmp/chrome_qa.log")

begin
  # Wait for Puma and Chrome
  40.times do
    begin
      Net::HTTP.get_response(URI("http://127.0.0.1:#{server_port}/up"))
      break
    rescue
      sleep 0.25
    end
  end

  targets = nil
  40.times do
    begin
      targets = JSON.parse(Net::HTTP.get(URI("http://127.0.0.1:#{debug_port}/json")))
      break if targets.any? { |t| t["type"] == "page" }
    rescue
      sleep 0.25
    end
  end

  ws_url = targets.find { |t| t["type"] == "page" }["webSocketDebuggerUrl"]
  cdp = CdpClient.new(ws_url)
  cdp.call("Page.enable")
  cdp.call("Runtime.enable")

  wait_for = ->(js_cond, desc) do
    30.times do
      val = cdp.eval_js(js_cond) rescue nil
      return val if val
      sleep 0.2
    end
    raise "Timed out waiting for: #{desc} (URL=#{cdp.eval_js("location.href")})"
  end

  # 1. Sign in as admin David
  cdp.call("Page.navigate", { url: "http://127.0.0.1:#{server_port}/session/new" })
  wait_for.call("!!document.querySelector(\"input[name=email_address]\")", "login form")
  cdp.eval_js(<<~JS)
    document.querySelector("input[name=email_address]").value = "david@37signals.com";
    document.querySelector("input[name=password]").value = "secret123456";
    document.querySelector("button[type=submit]").click();
  JS
  wait_for.call("location.pathname.startsWith(\"/rooms/\")", "redirect after login")

  # 2. Visit /account/edit and verify "Bots per member" label & default value 5
  cdp.call("Page.navigate", { url: "http://127.0.0.1:#{server_port}/account/edit" })
  wait_for.call("!!document.querySelector(\"#account_settings_bots_per_member\")", "account edit")

  info = cdp.eval_js(<<~JS)
    (() => {
      const label = [...document.querySelectorAll("label")].find(l => l.textContent.trim() === "Bots per member");
      const input = label && document.getElementById(label.htmlFor);
      const saveButtons = [...document.querySelectorAll("button")].filter(b => b.textContent.trim() === "Save changes");
      return {
        foundLabel: !!label,
        inputType: input?.type,
        inputValue: input?.value,
        saveButtonsCount: saveButtons.length
      };
    })()
  JS
  raise "Unexpected info: #{info}" unless info == { "foundLabel" => true, "inputType" => "number", "inputValue" => "5", "saveButtonsCount" => 1 }
  puts "Verified label & default 5 & single Save changes button: #{info}"

  # 3. Test auto-save via change event (e.g. Playwright fill() or blur/spinner) -> set to 3
  cdp.eval_js(<<~JS)
    const input = document.getElementById("account_settings_bots_per_member");
    input.value = "3";
    input.dispatchEvent(new Event("change", { bubbles: true }));
  JS
  sleep 0.6
  Account.uncached { raise "Expected 3 via change" unless Account.first.settings.bots_per_member == 3 }
  puts "Verified auto-save via change event -> 3"

  # 4. Test fill + immediate click on Save changes -> set to 2
  cdp.eval_js(<<~JS)
    const input = document.getElementById("account_settings_bots_per_member");
    input.focus();
    input.value = "2";
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
