    btn.click();
  JS
  sleep 0.6
  Account.uncached { raise "Expected 2 via fill+click" unless Account.first.settings.bots_per_member == 2 }
  puts "Verified fill + click Save changes -> 2"

  # 5. Test toggling Must be admin switch preserves bots_per_member == 2
  cdp.eval_js(<<~JS)
    document.getElementById("account_settings_restrict_room_creation_to_administrators").click();
  JS
  sleep 0.6
