    acc = Account.first
    raise "Expected restrict_room_creation true and bots_per_member 2, got #{acc.settings.inspect}" unless acc.settings.restrict_room_creation_to_administrators? && acc.settings.bots_per_member == 2
  end
  puts "Verified toggling Must be admin switch preserves bots_per_member == 2"

  # 6. Log out and sign in as member Kevin, create 2 bots, check limit UI & native confirm() delete
  cdp.call("Network.clearBrowserCookies") rescue cdp.call("Storage.clearCookies")
  cdp.call("Page.navigate", { url: "http://127.0.0.1:#{server_port}/session/new" })
  wait_for.call("!!document.querySelector(\"input[name=email_address]\")", "member login")
  cdp.eval_js(<<~JS)
    document.querySelector("input[name=email_address]").value = "kevin@37signals.com";
    document.querySelector("input[name=password]").value = "secret123456";
    document.querySelector("button[type=submit]").click();
  JS
  wait_for.call("location.pathname.startsWith(\"/rooms/\")", "member logged in")

  2.times do |i|
    cdp.call("Page.navigate", { url: "http://127.0.0.1:#{server_port}/bots" })
