require "socket"
require "net/http"
require "json"
require "websocket/driver"

class CdpClient
  class DriverEnv
    attr_reader :url
    def initialize(socket, url)
      @socket = socket
      @url = url
    end
    def write(data)
      @socket.write(data)
    end
  end

  def initialize(ws_url)
    uri = URI(ws_url)
    @socket = TCPSocket.new(uri.host, uri.port)
    @env = DriverEnv.new(@socket, ws_url)
    @driver = WebSocket::Driver.client(@env)
    @messages = []
    @open = false
    @id = 0

    @driver.on(:open) { @open = true }
    @driver.on(:message) do |event|
      msg = JSON.parse(event.data)
      @messages << msg if msg["id"]
    end

    @driver.start
    pump until @open
  end

  def pump
    data = @socket.readpartial(65536)
    @driver.parse(data)
  end

  def call(method, params = {})
    @id += 1
    req_id = @id
    @driver.text(JSON.generate({ id: req_id, method: method, params: params }))
    loop do
      found = @messages.find { |m| m["id"] == req_id }
      if found
        @messages.delete(found)
        raise "CDP error: #{found["error"]}" if found["error"]
        return found["result"]
      end
      pump
    end
  end

  def eval_js(expr)
    res = call("Runtime.evaluate", { expression: "(() => { #{expr} })()", awaitPromise: true, returnByValue: true })
    raise "JS exception: #{res["exceptionDetails"]}" if res["exceptionDetails"]
    res.dig("result", "value")
  end

  def close
    @socket.close rescue nil
  end
end

